# =============================================================================
# rollback_draft.ps1 -- Stage2 P0 rollback TEMPLATE (DRAFT, default DryRun)
#
# Scope: proposed P0 actions of this round (see S40 report.md):
#   P0-1 Third-party Unrestricted -> Auto        -> WHITELIST_RESTORE
#   P0-2 Tool-type apps -> Reduced               -> APPOPS_RESTORE / NETPOLICY_RESTORE
#   P0-3 com.qihoo.cleandroid_lite downgrade,
#        NOT uninstall                           -> APK_RESTORE
#   P0-4 U2 disable wave (pending confirmation)  -> UAD_RESTORE rows, status=PENDING
#
# Design: ledger-driven. The execution wave records the PRIOR state of every
# change it applies into rollback_plan.tsv (schema in rollback_plan.template.tsv)
# and flips the row status to EXECUTED. This script restores exactly those rows
# and never invents targets. Rows with status != EXECUTED (e.g. PENDING U2 rows)
# are skipped.
#
# Baseline captured 2026-08-23 (live/ snapshot, serial AVNS023705001888):
#   brand=HONOR model=VER-AN10 current_user=0 users={0,128}
#   netpolicy blacklist currently contains UID 10369 (io.github.sds100.keymapper)
#   com.honor.browser already disabled-user (prior=3 if the wave touches it)
#   com.qihoo.cleandroid_lite not whitelisted (prior=absent), appops default=allow
#
# Fail-closed guards:
#   G1 Device gate (execute only): exactly one authorized device with
#      serial AVNS023705001888, brand HONOR, model VER-AN10, current user 0.
#      Mismatch -> exit 2, zero commands.
#   G2 Plan rows must use an allowed category; unknown category -> exit 3.
#   G3 Only EXECUTED rows are restored; no target outside the plan.
#   G4 APK_RESTORE requires the backup artifact to exist and (if sha256 is
#      recorded) to match; otherwise exit 4 -> manual restore from the recorded
#      installer/source (com.hihonor.appmarket), never a downloaded unknown APK.
#   G5 Any command failure stops the run -> exit 5.
#   G6 -Verify post-checks whitelist/appops/netpolicy deterministically;
#      confirmed mismatch -> exit 6.
#
# Exit codes: 0=ok (incl. nothing to restore); 1=env/param/plan parse;
#             2=device gate; 3=plan guard; 4=APK backup guard;
#             5=command failure; 6=post-verify mismatch.
#
# Notes:
#   * This is a DRAFT produced by packet S40 and was NOT executed (no ADB call,
#     no device write). Run it only from an approved execution wave.
#   * PowerShell can mangle `settings get ...` argument forms; this template
#     performs no `settings get` query. If a future extension needs one, route
#     it through a Python subprocess.run([adb,'-s',serial,'shell',...]) helper.
#   * `cmd appops` / `cmd netpolicy` / `pm` syntax must be re-confirmed against
#     `cmd appops help` / `cmd netpolicy help` / `pm help` on the device at
#     execution time (unknown-API discipline); the commands below follow the
#     package playbook (02_COMMAND_PLAYBOOK.md).
# =============================================================================

[CmdletBinding()]
param(
    [switch]$Execute,
    [switch]$Verify,
    [string]$AdbPath = '',
    [string]$Serial = 'AVNS023705001888',
    [string]$PlanPath = '',
    [string]$JournalPath = ''
)

$ErrorActionPreference = 'Stop'
$script:ScriptRoot = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }
$script:RollbackExit = 1

function Resolve-AdbPath {
    if ($AdbPath) {
        if (-not (Test-Path -LiteralPath $AdbPath)) { throw 'AdbPath not found: ' + $AdbPath }
        return $AdbPath
    }
    $candidate = 'C:\Users\hzq00\Downloads\platform-tools-latest-windows\platform-tools\adb.exe'
    if (Test-Path -LiteralPath $candidate) { return $candidate }
    $cmd = Get-Command adb -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    throw 'adb not found; pass -AdbPath'
}

function Assert-DeviceGate {
    param([string]$Adb, [string]$Serial)
    $devices = @(& $Adb devices -l 2>&1)
    if ($LASTEXITCODE -ne 0) { throw 'adb devices failed with exit ' + $LASTEXITCODE }
    $lines = @($devices | Where-Object { $_ -match '\S' } | Select-Object -Skip 1)
    $hit = @($lines | Where-Object { $_ -match [regex]::Escape($Serial) -and $_ -match '\sdevice\s' })
    if ($lines.Count -ne 1 -or $hit.Count -ne 1) {
        Write-Host ('ROLLBACK GATE FAIL: expected exactly one authorized device ' + $Serial)
        $devices | ForEach-Object { Write-Host $_ }
        exit 2
    }
    $brand = ((& $Adb -s $Serial shell getprop ro.product.brand) -join '').Trim()
    $model = ((& $Adb -s $Serial shell getprop ro.product.model) -join '').Trim()
    $cur = ((& $Adb -s $Serial shell am get-current-user) -join '').Trim()
    if ($brand -ne 'HONOR' -or $model -ne 'VER-AN10' -or $cur -ne '0') {
        Write-Host ('ROLLBACK GATE FAIL: brand=' + $brand + ' model=' + $model + ' current_user=' + $cur)
        exit 2
    }
    Write-Host 'ROLLBACK GATE PASS'
}

function Read-RollbackPlan {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    $rows = @(Import-Csv -LiteralPath $Path -Delimiter "`t" -Encoding UTF8)
    $allowed = @('UAD_RESTORE', 'APPOPS_RESTORE', 'WHITELIST_RESTORE', 'NETPOLICY_RESTORE', 'APK_RESTORE')
    foreach ($r in $rows) {
        if (-not $r.category -or -not $r.package -or -not $r.status) {
            throw 'plan row missing required columns (category/package/status)'
        }
        if ($allowed -notcontains $r.category) {
            throw ('unknown category "' + $r.category + '" in plan; allowed: ' + ($allowed -join ', '))
        }
    }
    return $rows
}

function Get-RestoreCommand {
    param($row)
    if ($row.restore_command) { return $row.restore_command.Trim() }
    $pkg = $row.package
    $uid = $row.uid
    switch ($row.category) {
        'WHITELIST_RESTORE' {
            if ($row.prior_value -eq 'present') { return "dumpsys deviceidle whitelist +$pkg" }
            if ($row.prior_value -eq 'absent') { return "dumpsys deviceidle whitelist -$pkg" }
            throw ("WHITELIST_RESTORE prior_value must be present|absent, got '" + $row.prior_value + "'")
        }
        'APPOPS_RESTORE' {
            switch ($row.prior_value) {
                'default' { return "cmd appops reset --user 0 $pkg RUN_ANY_IN_BACKGROUND" }
                'allow'   { return "cmd appops set --user 0 $pkg RUN_ANY_IN_BACKGROUND allow" }
                'ignore'  { return "cmd appops set --user 0 $pkg RUN_ANY_IN_BACKGROUND ignore" }
                default { throw ("APPOPS_RESTORE prior_value must be default|allow|ignore, got '" + $row.prior_value + "'") }
            }
        }
        'NETPOLICY_RESTORE' {
            if ($row.prior_value -eq 'present') { return "cmd netpolicy add restrict-background-blacklist $uid" }
            if ($row.prior_value -eq 'absent') { return "cmd netpolicy remove restrict-background-blacklist $uid" }
            throw ("NETPOLICY_RESTORE prior_value must be present|absent, got '" + $row.prior_value + "'")
        }
        'UAD_RESTORE' {
            switch ($row.prior_value) {
                '0' { return "pm default-state --user 0 $pkg" }
                '1' { return "pm enable --user 0 $pkg" }
                '3' { return "pm disable-user --user 0 $pkg" }
                '4' { return "pm disable-user --user 0 $pkg" }
                default { throw ("UAD_RESTORE prior_value must be 0|1|3|4, got '" + $row.prior_value + "'; state 2 (disabled-until-used) needs a manual decision") }
            }
        }
        'APK_RESTORE' {
            if (-not $row.artifact) { throw 'APK_RESTORE requires artifact (backup apk path) in plan' }
            return "install -r -d $($row.artifact)"
        }
    }
    throw ('unhandled category: ' + $row.category)
}

function Assert-ApkBackup {
    param($row)
    if (-not (Test-Path -LiteralPath $row.artifact)) {
        $script:RollbackExit = 4
        throw ('APK_RESTORE backup missing: ' + $row.artifact + '; manual restore from recorded installer/source required (exit 4)')
    }
    if ($row.sha256) {
        $h = (Get-FileHash -LiteralPath $row.artifact -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($h -ne $row.sha256.ToLowerInvariant()) {
            $script:RollbackExit = 4
            throw ('APK_RESTORE sha256 mismatch: ' + $h + ' != ' + $row.sha256 + ' (exit 4)')
        }
    }
}

function Invoke-RestoreRow {
    param($row, [string]$Adb, [string]$Serial, [bool]$DryRun, [string]$Journal)
    $cmd = Get-RestoreCommand $row
    Write-Host ('ROLLBACK: [' + $row.category + '] ' + $row.package + ' -> ' + $cmd)
    if ($row.category -eq 'APK_RESTORE' -and -not (Test-Path -LiteralPath $row.artifact)) {
        Write-Host ('ROLLBACK WARNING: APK backup missing in dry-run: ' + $row.artifact)
    }
    if ($DryRun) { return }
    if ($row.category -eq 'APK_RESTORE') {
        Assert-ApkBackup $row
        & $Adb -s $Serial install -r -d $row.artifact
    } else {
        $parts = @($cmd -split '\s+')
        & $Adb -s $Serial shell @parts
    }
    if ($LASTEXITCODE -ne 0) {
        Write-Host ('ROLLBACK CMD FAIL: ' + $cmd + ' (exit ' + $LASTEXITCODE + ')')
        $script:RollbackExit = 5
        throw 'command failed: ' + $cmd
    }
    $line = (Get-Date -Format o) + "`t" + $row.category + "`t" + $row.package + "`t" + $cmd + "`tOK"
    Add-Content -LiteralPath $Journal -Value $line -Encoding UTF8
}

function Invoke-RestoreVerify {
    param($row, [string]$Adb, [string]$Serial)
    # Returns $true=verified, $false=confirmed mismatch, $null=not mechanically checkable.
    $pkg = $row.package
    switch ($row.category) {
        'WHITELIST_RESTORE' {
            $out = ((& $Adb -s $Serial shell dumpsys deviceidle whitelist) -join "`n")
            $rx = ',' + [regex]::Escape($pkg) + ','
            $present = $out -match $rx
            if ($row.prior_value -eq 'present') { return $present }
            if ($row.prior_value -eq 'absent') { return (-not $present) }
            return $null
        }
        'APPOPS_RESTORE' {
            $out = ((& $Adb -s $Serial shell cmd appops query-op --user 0 RUN_ANY_IN_BACKGROUND ignore) -join "`n")
            $present = $out -match [regex]::Escape($pkg)
            if ($row.prior_value -eq 'ignore') { return $present }
            if ($row.prior_value -in @('default', 'allow')) { return (-not $present) }
            return $null
        }
        'NETPOLICY_RESTORE' {
            $out = ((& $Adb -s $Serial shell cmd netpolicy list restrict-background-blacklist) -join "`n")
            $present = $out -match ('\b' + [regex]::Escape([string]$row.uid) + '\b')
            if ($row.prior_value -eq 'present') { return $present }
            if ($row.prior_value -eq 'absent') { return (-not $present) }
            return $null
        }
        'UAD_RESTORE' {
            $out = ((& $Adb -s $Serial shell dumpsys package $pkg) -join "`n")
            $m = [regex]::Match($out, 'enabled=(\d)')
            Write-Host ('ROLLBACK VERIFY UAD ' + $pkg + ' enabled=' + $(if ($m.Success) { $m.Groups[1].Value } else { 'unparseable' }))
            return $null
        }
        'APK_RESTORE' {
            $out = ((& $Adb -s $Serial shell dumpsys package $pkg) -join "`n")
            $vm = [regex]::Match($out, 'versionName=(\S+)')
            $cm = [regex]::Match($out, 'versionCode=(\S+)')
            Write-Host ('ROLLBACK VERIFY APK ' + $pkg + ' versionCode=' + $(if ($cm.Success) { $cm.Groups[1].Value } else { 'unparseable' }) + ' versionName=' + $(if ($vm.Success) { $vm.Groups[1].Value } else { 'unparseable' }))
            return $null
        }
    }
    return $null
}

try {
    $adb = Resolve-AdbPath
    $planPath = if ($PlanPath) { $PlanPath } else { Join-Path $script:ScriptRoot 'rollback_plan.tsv' }
    $planFull = [System.IO.Path]::GetFullPath($planPath)
    $rows = Read-RollbackPlan -Path $planFull
    if ($null -eq $rows) {
        Write-Host ('ROLLBACK: plan not found at ' + $planFull + '; nothing recorded, nothing to restore (exit 0)')
        exit 0
    }
    $targets = @($rows | Where-Object { $_.status -eq 'EXECUTED' })
    if ($targets.Count -eq 0) {
        Write-Host 'ROLLBACK: plan has no EXECUTED rows (all pending); nothing to restore (exit 0)'
        exit 0
    }
    $skipped = @($rows | Where-Object { $_.status -ne 'EXECUTED' }).Count
    Write-Host ('ROLLBACK: plan ' + $rows.Count + ' rows; restoring ' + $targets.Count + ' EXECUTED (skipping ' + $skipped + ' non-executed)')

    if (-not $Execute) {
        Write-Host 'ROLLBACK DRYRUN: no ADB calls, nothing changed.'
        foreach ($row in $targets) { Invoke-RestoreRow -row $row -Adb $adb -Serial $Serial -DryRun $true -Journal '' }
        Write-Host 'ROLLBACK DRYRUN: re-run with -Execute to apply.'
        exit 0
    }

    Assert-DeviceGate -Adb $adb -Serial $Serial

    $journal = if ($JournalPath) { $JournalPath } else { Join-Path (Split-Path $planFull) 'rollback_journal.tsv' }
    $journalDir = Split-Path $journal
    if ($journalDir -and -not (Test-Path -LiteralPath $journalDir)) {
        New-Item -ItemType Directory -Path $journalDir -Force | Out-Null
    }
    if (-not (Test-Path -LiteralPath $journal)) {
        Add-Content -LiteralPath $journal -Value ("ts`tcategory`tpackage`tcommand`tresult") -Encoding UTF8
    }

    foreach ($row in $targets) {
        Invoke-RestoreRow -row $row -Adb $adb -Serial $Serial -DryRun $false -Journal $journal
    }

    if ($Verify) {
        $mismatch = 0
        foreach ($row in $targets) {
            $res = Invoke-RestoreVerify -row $row -Adb $adb -Serial $Serial
            if ($res -eq $false) {
                Write-Host ('ROLLBACK VERIFY MISMATCH: ' + $row.package)
                $mismatch++
            }
        }
        if ($mismatch -gt 0) {
            Write-Host ('ROLLBACK: ' + $mismatch + ' verification mismatch(es)')
            exit 6
        }
        Write-Host 'ROLLBACK VERIFY PASS'
    }
    Write-Host 'ROLLBACK: done (exit 0)'
    exit 0
} catch {
    Write-Host ('ROLLBACK ERROR: ' + $_.Exception.Message)
    exit $script:RollbackExit
}

